import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{St as i,xt as a}from"./chunks/assets.DAjhvrpn.js";var o=JSON.parse(`{"title":"Projection","description":"","frontmatter":{"title":"Projection","lang":"en-US"},"headers":[],"relativePath":"maintenance/projection.md","filePath":"maintenance/projection.md"}`),s={name:`maintenance/projection.md`};function c(n,o,s,c,l,u){return e(),r(`div`,null,[...o[0]||=[t(`<h1 id="projection" tabindex="-1">Projection <a class="header-anchor" href="#projection" aria-label="Permalink to “Projection”">​</a></h1><p>Maintenance of the projection module consists mainly of the initial calibration, recalibration every ~6 months, and replacing the projector bulb whenever the projector asks for it (the projector keeps count of the bulb&#39;s hours of use).</p><h2 id="projection-calibration" tabindex="-1">Projection calibration <a class="header-anchor" href="#projection-calibration" aria-label="Permalink to “Projection calibration”">​</a></h2><p>The projection system uses a spherical mirror to project onto the dome. The image transformation is based on a <a href="http://www.domerama.com/general/geodesic-dome-projection/hemispherical-dome-projection/" target="_blank" rel="noreferrer">hemispherical dome projection principle</a>.</p><p>Creating correctly warped images for a particular projector, mirror and dome arrangement requires finding the point on the projector frustum for any point on the dome. The problem is three-dimensional, but it can be turned into a simpler two-dimensional problem by first translating the geometry so the spherical mirror is at the origin, and then rotating it so that the points on the mirror, dome and projector lie in a single plane.</p><p>The projector is located at P1, the mirror is of radius r, and the position on the dome is P2. The path length from the projector to the mirror is L1, and the path length from the dome to the mirror is L2.</p><p>Fermat’s principle states that light travels by the shortest route, so the reflection point on the mirror can be found by minimizing the total light path length from the projector to the position on the dome, namely L1 + L2. This is quite simple for a spherical mirror: the line at mid-angle between the vectors OP1 and OP2 and its intersection with the surface of the mirror defines the reflection point.</p><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><p>The projection calibration aligns the projection within certain boundaries: the horizon, the center, and the left and right sides are aligned to the physical position of the dome. This method trades off the time invested in the alignment against the accuracy of the rendered projection, since the height of the towers might differ across systems.</p><p>To calibrate the projection:</p><ol><li>Turn on the projector and make sure to mirror the projection horizontally; otherwise, left and right will be swapped.</li><li>Place the alignment tool. We recommend a <a href="https://www.grainger.com/product/BOSCH-Alignment-Laser-3-Beams-450W78?internalSearchTerm=Alignment+Laser%3A+3+Beams%2C+0+Dots%2C+0+Lines%2C+Red%2C+200+ft+Range+w%2Fo+Detector&amp;suggestConfigId=8&amp;searchBar=true&amp;opr=THKS" target="_blank" rel="noreferrer">3-beam laser alignment tool</a>. Use the lines marked on the bottom plate to align the center and side lasers on the dome. Set the horizontal laser 12&quot; above the bottom plate.</li><li>Create a new subject in the ViRMEn training GUI and select the <code>livecalibration.mat</code> experiment, our calibration world. Simulation mode must be set to true in the <code>RigParameters</code> file. This projects a static world with 3 towers: one at the center and one to the left and right of the mouse&#39;s eyes. The goal is to align the horizon with the animal&#39;s eye level, the center tower with the center of the screen, and the left and right towers with the position of the mouse&#39;s eyes.</li><li>Set the initial values of the projection parameters as below (these values were obtained empirically and are a good starting point for training mini VR rigs built as described here).</li></ol><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%% Mini VR projection parameters</span></span>
<span class="line"><span>% Spherical screen radius</span></span>
<span class="line"><span>proj_param_Rs           =    8;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Screen&#39;s center location relative to the animal eyes</span></span>
<span class="line"><span>proj_param_xsm          =    1.814;</span></span>
<span class="line"><span>proj_param_ysm          =    0;</span></span>
<span class="line"><span>proj_param_zsm          =    0.47;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Mirror position relative to the animal eyes</span></span>
<span class="line"><span>% Mirror position measurement is facilitated knowing that the center of</span></span>
<span class="line"><span>%spherical mirror is (43.8-24.2=)19.6mm (0.77in) behind the back surface.</span></span>
<span class="line"><span>proj_param_xOm          =   5.582;</span></span>
<span class="line"><span>proj_param_yOm          =   0;</span></span>
<span class="line"><span>proj_param_zOm          =   -6.62;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Radius of the spherical mirror (Silver coated lens LA1740-Thorlabs)</span></span>
<span class="line"><span>proj_param_r            =   1.724;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Projector position relative to the mirror center</span></span>
<span class="line"><span>proj_param_xP1o         =   11.1;</span></span>
<span class="line"><span>proj_param_yP1o         =   0;</span></span>
<span class="line"><span>proj_param_zP1o         =   -0.6;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Horizontal coordinate shift and rescaling</span></span>
<span class="line"><span>proj_param_hrescaling   =   5.5;</span></span>
<span class="line"><span>proj_param_hshift       =   0.000;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>% Vertical coordinate shift and rescaling</span></span>
<span class="line"><span>proj_param_vrescaling   =   5.5;</span></span>
<span class="line"><span>proj_param_vshift       =   -1.017;</span></span></code></pre></div><ol start="5"><li>First, align what you can by physically moving the projector. Unscrew the plate that holds the projector and move it horizontally until the middle tower is centered on the laser. Make sure that the left and right towers are equidistant from the middle of the dome; you may be able to achieve this by moving one side of the plate slightly forward.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The towers will shift when the plate is tightened. Don&#39;t loosen the screws all the way unless necessary: loosen them just enough to move the plate while checking the projection, then tighten them and adjust accordingly.</p></div><p>Doing this physically, instead of changing the projection transformation parameters, reduces the differences between the projections of different training rigs.</p><ol start="6"><li>Adjust the rest of the parameters until the towers and horizon are aligned. Below is a brief description of how each parameter changes the projection.</li></ol><ul><li><strong>Rs</strong> should not be modified.</li><li><strong>xsm</strong> adjusts the height of the middle tower without affecting the lateral towers; values should be around 1.5 to 2. This value can be adjusted, since each screen has its own quirks from fabrication.</li><li><strong>zOm</strong> adjusts the horizon. This value can be adjusted, since mirrors can differ in how they are glued to their aluminum base.</li><li><strong>xP1o</strong> stretches or shrinks the lateral towers, and <strong>zP1o</strong> lowers or raises the middle tower but also changes the distal part of the lateral towers. These values can be adjusted, since the projection origin differs slightly between individual projectors.</li><li><strong>hrescaling</strong> and <strong>vrescaling</strong> should be equal; otherwise, the projection is stretched or squeezed, and there will be significant differences across systems.</li><li><strong>hshift</strong> and <strong>vshift</strong> move the entire projection up, down, left or right. Ideally, <strong>hshift</strong> should be 0 if the projection is calibrated manually, but it can be changed if necessary, since it shouldn&#39;t significantly affect the projection across different systems.</li></ul><figure><img src="`+a+`" alt="Projection calibration. Because of how spherical mirror projection works, the lateral towers will be slightly curved; the projection is fine as long as they are equidistant and centered at the top (or the bottom; just keep the same convention across rigs)." width="1280" height="932" loading="lazy"><figcaption>Projection calibration. Because of how spherical mirror projection works, the lateral towers will be slightly curved; the projection is fine as long as they are equidistant and centered at the top (or the bottom; just keep the same convention across rigs).</figcaption></figure><h2 id="projector-bulb-replacement" tabindex="-1">Projector bulb replacement <a class="header-anchor" href="#projector-bulb-replacement" aria-label="Permalink to “Projector bulb replacement”">​</a></h2><p>The projector counts how long the bulb has been used and alerts you when it should be replaced. Keep projector bulbs in stock, and follow the projector&#39;s instructions to replace them.</p>`,20)]])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};